import itertools, json
import numpy as np
import pandas as pd
from scipy.optimize import minimize

df=pd.read_csv('data.csv')
bands=list(df['band'].drop_duplicates())
periods=sorted(df['period_id'].unique(), key=lambda x:int(x[1:]))
Y=np.array([[df[(df.band==b)&(df.period_id==p)].mean_value.iloc[0] for p in periods] for b in bands],float)

def simplex_fit(A,y):
    # A: features x k, y features
    k=A.shape[1]
    if k==1:
        return np.ones(1), np.mean((A[:,0]-y)**2)
    def obj(w):
        r=A@w-y
        return float(np.mean(r*r))
    cons={'type':'eq','fun':lambda w: np.sum(w)-1}
    bounds=[(0,None)]*k
    best=None
    for x0 in [np.ones(k)/k]+[np.eye(k)[i] for i in range(k)]:
        res=minimize(obj,x0,method='SLSQP',bounds=bounds,constraints=cons,
                     options={'ftol':1e-12,'maxiter':1000, 'disp':False})
        if res.success:
            val=obj(res.x)
            if best is None or val<best[1]:
                best=(res.x,val)
    if best is None:
        w=np.ones(k)/k
        return w,obj(w)
    w=best[0].clip(0); w=w/w.sum()
    return w,obj(w)

def shc_observed(m):
    n=1
    starts=list(range(0,9-m-n+1))
    target=Y[:,9-m:9].reshape(-1)
    match=[]; fwd=[]
    for s in starts:
        match.append(Y[:,s:s+m].reshape(-1))
        fwd.append(Y[:,s+m])
    match=np.array(match).T
    fwd=np.array(fwd).T
    best=None
    # exhaustive subset, small; slight complexity penalty to avoid needless exact-ish mixes
    for r in range(1,len(starts)+1):
        for sub in itertools.combinations(range(len(starts)),r):
            A=match[:,sub]
            w,err=simplex_fit(A,target)
            score=err*(1+0.03*(r-1))  # parsimonious tie/overfit guard
            if best is None or score<best['score']:
                pred=fwd[:,sub]@w
                best={'m':m,'sub':sub,'w':w,'err':err,'score':score,'pred':pred}
    return best

# Use multiple plausible matching lengths.  Weight by in-sample matching accuracy;
# with nine months, relying on a single m is unstable.
models=[shc_observed(m) for m in range(2,6)]  # leaves at least 3 historical blocks
errs=np.array([md['err'] for md in models])
# inverse-error weights with floor for numerical stability
mw=1/np.maximum(errs,1e-6)
mw=mw/mw.sum()
pred=sum(w*md['pred'] for w,md in zip(mw,models))

for b,v in zip(bands,pred):
    print(b, f"{v:.6f}")
